// Byte-exact parity with the desktop's hardware-verified Python tools (tools/edge500_profile.py,
// edge500_course.py, edge500_workout.py): the fixture is generated by running them on FIT files
// laid out like a real Edge 500's (built in the generator, so no device serial is in it), so a
// drift in either port fails here.
import fx from './edge500.fixture.json';
import { buildEdge500Profile, readEdge500Profile, fitCrc, pyFixed, pyRound } from '../Edge500Profile';
import { parseGpx, toTcx, courseName, courseFileName } from '../Edge500Course';
import { encodeEdge500Workout, workoutName, workoutFileName } from '../Edge500Workout';

const hex = (b: Uint8Array) => Array.from(b, x => x.toString(16).padStart(2, '0')).join('');
const bytes = (h: string) => new Uint8Array((h.match(/../g) ?? []).map(x => parseInt(x, 16)));

describe('Python number formatting twins', () => {
  it('round() and %.Nf go to the even neighbour on exact ties', () => {
    expect([pyRound(0.5), pyRound(1.5), pyRound(2.5), pyRound(-0.5), pyRound(2.4999)]).toEqual([0, 2, 2, 0, 2]);
    expect([pyFixed(100.25, 1), pyFixed(12.75, 1), pyFixed(-2.25, 1), pyFixed(0.125, 2), pyFixed(1.05, 1)])
      .toEqual(['100.2', '12.8', '-2.2', '0.12', '1.1']);
  });
});

describe('Edge 500 profile matches tools/edge500_profile.py', () => {
  it('reads every file the way the Python tool does', () => {
    for (const r of fx.profileReads) {
      expect(readEdge500Profile(bytes(r.settings), bytes(r.cycling))).toEqual(r.profile);
    }
  });
  it('patches byte for byte (values, zones, CRC)', () => {
    for (const c of fx.profileCases) {
      const s = bytes(c.settings), cy = bytes(c.cycling);
      const out = buildEdge500Profile(s, cy, c.changes as any);
      expect(out.settings ? hex(out.settings) : null).toBe(c.outSettings);
      expect(out.cycling ? hex(out.cycling) : null).toBe(c.outCycling);
      expect(out.changed).toEqual(c.changed);
      if (out.settings) expect(fitCrc(out.settings)).toBe(0);
      if (out.cycling) expect(fitCrc(out.cycling)).toBe(0);
      expect(hex(s)).toBe(c.settings);                    // the input is never touched
    }
  });
  it('refuses out-of-range values', () => {
    const c = fx.profileCases[0];
    for (const bad of fx.profileErrors) {
      expect(() => buildEdge500Profile(bytes(c.settings), bytes(c.cycling), bad as any)).toThrow();
    }
  });
});

describe('Edge 500 course matches tools/edge500_course.py', () => {
  it('GPX -> TCX, same text', () => {
    for (const c of fx.courses) {
      const pts = parseGpx(c.gpx);
      expect(pts).toEqual(c.points);
      expect(courseName(c.name)).toBe(c.courseName);
      expect(courseFileName(c.name)).toBe(c.fileName);
      expect(toTcx(pts, c.name)).toBe(c.tcx);
    }
  });
  it('thins a long route to 3000 points, same text', () => {
    const big: [number, number, number][] = [];
    for (let i = 0; i < fx.bigCourse.n; i++) big.push([41.0 + i * 0.0001, -8.6 + (i % 7) * 0.00003, 50 + (i % 13) * 0.25]);
    const tcx = toTcx(big, 'Brevet 600');
    expect((tcx.match(/<Trackpoint>/g) ?? []).length).toBe(fx.bigCourse.trackpoints);
    let h = 0x811c9dc5;                                    // FNV-1a over the text (the fixture's too)
    for (let i = 0; i < tcx.length; i++) h = Math.imul(h ^ tcx.charCodeAt(i), 0x01000193) >>> 0;
    expect(tcx.length).toBe(fx.bigCourse.length);
    expect(h).toBe(fx.bigCourse.fnv1a);
  });
  it('refuses a one-point route', () => {
    expect(() => toTcx([[41, -8, null]], 'x')).toThrow();
  });
});

describe('Edge 500 workout matches tools/edge500_workout.py', () => {
  it('schema workout -> FIT workout, same bytes', () => {
    for (const w of fx.workouts) {
      expect(workoutName(w.workout, w.name)).toBe(w.wname);
      expect(workoutFileName(w.workout, w.name)).toBe(w.fileName);
      const fit = encodeEdge500Workout(w.workout, w.name);
      expect(hex(fit)).toBe(w.fit);
      expect(fitCrc(fit)).toBe(0);
    }
  });
  it('refuses broken workouts', () => {
    for (const bad of fx.workoutErrors) expect(() => encodeEdge500Workout(bad)).toThrow();
  });
});
